/**
 * n8n Code node
 * Input: items like [{ json: { output: "<JSON string>" } }]
 * Output: one flattened object with useful fields
 */

function safeParseStrJson(maybeStr, fallback = {}) {
  if (maybeStr == null) return fallback;
  if (typeof maybeStr === 'object') return maybeStr; // already parsed
  try {
    return JSON.parse(String(maybeStr));
  } catch {
    return fallback;
  }
}

function joinArr(arr) {
  if (!Array.isArray(arr)) return '';
  return arr.join(' | ');
}

const items = $input.all();
const out = [];

// Your sample appears to be a *single* item array
for (const item of items) {
  const raw = item.json ?? item;

  // The interesting payload sits inside `output` as a JSON string
  const parsed = safeParseStrJson(raw.output, {});

  const overall_score = parsed.overall_score ?? null;

  const cs = parsed.category_scores ?? {};
  const category_scores = {
    data_validation_and_processing: cs.data_validation_and_processing ?? null,
    analysis_reporting_SOPs: cs.analysis_reporting_SOPs ?? null,
    workflow_standardization_documentation: cs.workflow_standardization_documentation ?? null,
    issue_troubleshooting_ad_hoc: cs.issue_troubleshooting_ad_hoc ?? null,
    stakeholder_collaboration: cs.stakeholder_collaboration ?? null,
    self_management_and_continuous_improvement: cs.self_management_and_continuous_improvement ?? null,
    tooling_excel_sql_analytics: cs.tooling_excel_sql_analytics ?? null,
    communication_written_english: cs.communication_written_english ?? null,
  };

  const strengths = Array.isArray(parsed.strengths) ? parsed.strengths : [];
  const improvement_areas = Array.isArray(parsed.improvement_areas) ? parsed.improvement_areas : [];
  const keyword_recommendations = Array.isArray(parsed.keyword_recommendations) ? parsed.keyword_recommendations : [];
  const tailored_bullets = Array.isArray(parsed.tailored_bullets) ? parsed.tailored_bullets : [];

  const gaps = parsed.gaps_and_learning_plan ?? {};
  const quick_wins = Array.isArray(gaps.quick_wins_1_2_weeks) ? gaps.quick_wins_1_2_weeks : [];
  const medium_horizon = Array.isArray(gaps.medium_horizon_1_2_months) ? gaps.medium_horizon_1_2_months : [];

  const ats_tips = Array.isArray(parsed.ats_tips) ? parsed.ats_tips : [];

  const company = parsed.company_insights ?? {};
  const company_highlights = Array.isArray(company.highlights) ? company.highlights : [];
  const company_sources = Array.isArray(company.sources) ? company.sources : [];
  const company_research_status = company.research_status ?? '';

  const summary = parsed.summary ?? '';

  // Build a flat, sheet-friendly record
  const record = {
    overall_score,

    // Category scores
    cs_data_validation_and_processing: category_scores.data_validation_and_processing,
    cs_analysis_reporting_SOPs: category_scores.analysis_reporting_SOPs,
    cs_workflow_standardization_documentation: category_scores.workflow_standardization_documentation,
    cs_issue_troubleshooting_ad_hoc: category_scores.issue_troubleshooting_ad_hoc,
    cs_stakeholder_collaboration: category_scores.stakeholder_collaboration,
    cs_self_management_and_continuous_improvement: category_scores.self_management_and_continuous_improvement,
    cs_tooling_excel_sql_analytics: category_scores.tooling_excel_sql_analytics,
    cs_communication_written_english: category_scores.communication_written_english,

    // Arrays joined with " | " for easy viewing in Sheets
    strengths_all: joinArr(strengths),
    strengths_1: strengths[0] ?? '',
    strengths_2: strengths[1] ?? '',
    strengths_3: strengths[2] ?? '',

    improvement_areas_all: joinArr(improvement_areas),
    improvement_1: improvement_areas[0] ?? '',
    improvement_2: improvement_areas[1] ?? '',
    improvement_3: improvement_areas[2] ?? '',

    keyword_recommendations_all: joinArr(keyword_recommendations),

    tailored_bullets_all: joinArr(tailored_bullets),
    tailored_bullet_1: tailored_bullets[0] ?? '',
    tailored_bullet_2: tailored_bullets[1] ?? '',
    tailored_bullet_3: tailored_bullets[2] ?? '',

    quick_wins_all: joinArr(quick_wins),
    quick_win_1: quick_wins[0] ?? '',
    quick_win_2: quick_wins[1] ?? '',

    medium_horizon_all: joinArr(medium_horizon),
    medium_horizon_1: medium_horizon[0] ?? '',
    medium_horizon_2: medium_horizon[1] ?? '',

    ats_tips_all: joinArr(ats_tips),

    company_research_status,
    company_highlights_all: joinArr(company_highlights),
    company_sources_all: joinArr(company_sources),

    summary,
  };

  out.push({ json: record });
}

// If your input is a single element array, returning the first is fine,
// but returning all keeps it generic for future batches.
return out;

// Get incoming items as plain JSON
const items = $input.all().map(i => i.json);

// Canonical section names to recognize directly (case-insensitive, optional trailing colon)
const KNOWN_SECTIONS = [
  "Personal Information",
  "Contact",
  "Summary",
  "Profile",
  "Objective",
  "Education",
  "Work Experience",
  "Experience",
  "Professional Experience",
  "Projects",
  "Skills",
  "Technical Skills",
  "Certifications",
  "Awards",
  "Publications",
  "Activities",
  "Volunteer",
  "Languages",
  "Interests",
  "References"
];

// For fast case-insensitive comparison
const KNOWN_SET = new Set(KNOWN_SECTIONS.map(s => s.toLowerCase()));

function titleCase(s) {
  return s.replace(/\w\S*/g, w => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase());
}

function normalizeHeadingText(line) {
  return line.replace(/:$/, '').trim();
}

// Returns a canonical section name if line looks like a heading; otherwise null
function detectHeading(line) {
  const trimmed = normalizeHeadingText(line);
  const lc = trimmed.toLowerCase();

  // 1) Direct match against known sections
  if (KNOWN_SET.has(lc)) return titleCase(trimmed);

  // 2) Heuristic heading detection
  //    - At least one run of 4+ consecutive uppercase letters (e.g., "WORK EXPERIENCE")
  //    - Reasonably short line (≤ 80 chars)
  //    - Uppercase ratio high (> 0.6)
  //    - Avoid lines that look like data (numbers, emails)
  const hasUpperRun = /[A-Z]{4,}/.test(trimmed);
  const isShort = trimmed.length <= 80;
  const uppercaseCount = (trimmed.match(/[A-Z]/g) || []).length;
  const alphaCount = (trimmed.match(/[A-Za-z]/g) || []).length;
  const uppercaseRatio = alphaCount ? (uppercaseCount / alphaCount) : 0;
  const looksLikeData = /\d/.test(trimmed) || /@/.test(trimmed);

  if (hasUpperRun && isShort && uppercaseRatio > 0.6 && !looksLikeData) {
    // Map common variants into canonical names when possible
    const canonicalGuesses = [
      ["work experience", "Work Experience"],
      ["professional experience", "Work Experience"],
      ["experience", "Work Experience"],
      ["technical skills", "Skills"],
      ["skills", "Skills"],
      ["education", "Education"],
      ["projects", "Projects"],
      ["certifications", "Certifications"],
      ["awards", "Awards"],
      ["publications", "Publications"],
      ["activities", "Activities"],
      ["volunteer", "Volunteer"],
      ["languages", "Languages"],
      ["interests", "Interests"],
      ["references", "References"],
      ["summary", "Summary"],
      ["profile", "Profile"],
      ["objective", "Objective"],
      ["contact", "Contact"],
      ["personal information", "Personal Information"]
    ];

    for (const [needle, canon] of canonicalGuesses) {
      if (lc.includes(needle)) return canon;
    }

    // Fallback: title-case the detected heading
    return titleCase(trimmed);
  }

  return null;
}

const parsedResumes = items.map((item) => {
  const parsed = {};               // { [section: string]: string[] }
  const order = [];                // keep section order if needed
  let currentSection = null;

  const text = (item.text || "").replace(/\r/g, "");
  const lines = text.split("\n").map(l => l.trim()).filter(l => l.length > 0);

  for (const rawLine of lines) {
    const line = rawLine.replace(/\s+/g, ' ').trim();
    const maybeHeading = detectHeading(line);

    if (maybeHeading) {
      currentSection = maybeHeading;
      if (!parsed[currentSection]) {
        parsed[currentSection] = [];
        order.push(currentSection);
      }
      continue;
    }

    // If we haven't seen any section yet, bucket into "Misc"
    if (!currentSection) {
      currentSection = "Misc";
      if (!parsed[currentSection]) {
        parsed[currentSection] = [];
        order.push(currentSection);
      }
    }

    parsed[currentSection].push(line);
  }

  // Join arrays into newline-separated strings for output compatibility
  const joined = Object.fromEntries(
    Object.entries(parsed).map(([k, arr]) => [k, arr.join("\n")])
  );

  // If you also want to expose the section order, uncomment:
  // joined._section_order = order;

  return { json: joined };
});

return parsedResumes;

// This Code node takes the incoming Webhook item(s)
// and outputs only the `body` portion as plain JSON.
//
// Example Input:  [{ headers: {...}, body: {...}, ... }]
// Example Output: [{ job_title: "...", job_description: "...", company_url: "..." }]

return $input.all().map(item => {
  const body = item.json.body ?? {};
  return { json: body };
});

// Get both input items
const items = $input.all();

// Expecting two items: one resume, one job description
if (items.length < 2) {
  throw new Error("Expected two items: [resumeObject, jobObject]");
}

// Extract both
const resume = items[0].json;
const job = items[1].json;

// Merge both into one unified structure
const merged = {
  resume_data: resume,
  job_posting: {
    title: job.job_title || "",
    description: job.job_description || "",
    company_url: job.company_url || ""
  }
};

// Return a single item
return [{ json: merged }];

